def safe_float(x):
    try:
        arr = np.asarray(x, dtype=float).ravel()
        return float(arr[0]) if arr.size else np.nan
    except Exception:
        return np.nan


def sample_entropy(rr, m=2, r=None):
    rr = np.asarray(rr, dtype=float)
    rr = rr[np.isfinite(rr)]
    n = len(rr)
    if n < m + 2:
        return np.nan
    if r is None:
        sd = np.std(rr, ddof=0)
        r = 0.2 * sd
    if not np.isfinite(r) or r <= 0:
        return np.nan

    def count(mm):
        templates = np.array([rr[i:i + mm] for i in range(n - mm + 1)])
        c = 0
        for i in range(len(templates) - 1):
            dist = np.max(np.abs(templates[i + 1:] - templates[i]), axis=1)
            c += int(np.sum(dist <= r))
        return c

    b = count(m)
    a = count(m + 1)
    if a <= 0 or b <= 0:
        return np.nan
    return float(-np.log(a / b))


def dfa_alpha(rr):
    x = np.asarray(rr, dtype=float)
    x = x[np.isfinite(x)]
    n = len(x)
    if n < 32:
        return np.nan
    y = np.cumsum(x - np.mean(x))
    max_scale = min(16, n // 4)
    if max_scale < 5:
        return np.nan
    scales = np.unique(np.floor(np.logspace(np.log10(4), np.log10(max_scale), 8)).astype(int))
    fs = []
    used = []
    for s in scales:
        if s < 4 or n // s < 2:
            continue
        rms = []
        for start in range(0, n - s + 1, s):
            seg = y[start:start+s]
            t = np.arange(s)
            coef = np.polyfit(t, seg, 1)
            trend = np.polyval(coef, t)
            rms.append(np.sqrt(np.mean((seg - trend) ** 2)))
        if rms:
            f = np.sqrt(np.mean(np.asarray(rms) ** 2))
            if np.isfinite(f) and f > 0:
                used.append(s)
                fs.append(f)
    if len(fs) < 2:
        return np.nan
    return float(np.polyfit(np.log(used), np.log(fs), 1)[0])


def fallback_peaks(ecg, fs):
