#!/usr/bin/env python3
"""
Proper RRV analysis for the provided bio_eventrelated_100hz.csv.

The input file was located at:
  /data/lab/sab_data/benchmark_verified/benchmark/datasets/biosignals/bio_eventrelated_100hz.csv

This script performs a fresh analysis:
- cleans the RSP signal
- extracts inhalation peaks and respiratory-rate peaks
- computes RRV time-domain, frequency-domain, nonlinear, rate, and amplitude features
- attempts to augment with NeuroKit2 RRV features if NeuroKit2 is available
- saves pred_results/rrv_analysis_pred.csv
"""

import os
import json
import warnings
from pathlib import Path

import numpy as np
import pandas as pd
from scipy import signal, interpolate, stats

warnings.filterwarnings("ignore")

FS = 100.0
TARGET = "bio_eventrelated_100hz.csv"
OUTDIR = Path("pred_results")
OUTFILE = OUTDIR / "rrv_analysis_pred.csv"


def find_input_file():
    candidates = [
        Path("biosignals") / TARGET,
        Path("benchmark/datasets/biosignals") / TARGET,
        Path("/data/lab/sab_data/benchmark_verified/benchmark/datasets/biosignals") / TARGET,
        Path("/data/lab/sab_data/benchmark/datasets/biosignals") / TARGET,
        Path("/mnt/data/biosignals") / TARGET,
        Path(TARGET),
    ]
    for p in candidates:
        if p.exists():
            return p

    roots = [Path("."), Path("/data/lab/sab_data"), Path("/data/lab/VeriFront")]
    for root in roots:
        if root.exists():
            try:
                hits = list(root.rglob(TARGET))
                if hits:
                    return hits[0]
            except Exception as e:
                print(f"Search warning for {root}: {e}")
    raise FileNotFoundError(f"Could not locate {TARGET}")


def numeric_clean_series(s):
    x = pd.to_numeric(pd.Series(s), errors="coerce").astype(float)
    if x.isna().any():
        x = x.interpolate(limit_direction="both").ffill().bfill()
    return x.to_numpy(dtype=float)


def bandpass_clean_rsp(rsp, fs=100.0, low=0.05, high=1.0, order=4):
    x = np.asarray(rsp, dtype=float)
    x = signal.detrend(x, type="linear")
    nyq = fs / 2.0
    b, a = signal.butter(order, [low / nyq, high / nyq], btype="bandpass")
    return signal.filtfilt(b, a, x)


def detect_inhalation_peaks(clean, fs=100.0):
    x = np.asarray(clean, dtype=float)
    robust_sd = 1.4826 * np.nanmedian(np.abs(x - np.nanmedian(x)))
    if not np.isfinite(robust_sd) or robust_sd <= 0:
        robust_sd = np.nanstd(x)
    if not np.isfinite(robust_sd) or robust_sd <= 0:
        robust_sd = 1.0

    best_peaks = np.array([], dtype=int)
    best_props = {}
    distance = int(round(1.5 * fs))
    for prom_factor in [0.45, 0.35, 0.25, 0.15, 0.08, 0.04]:
        peaks, props = signal.find_peaks(x, distance=distance, prominence=prom_factor * robust_sd)
        if len(peaks) > len(best_peaks):
            best_peaks = peaks
            best_props = props
        if len(peaks) >= 5:
            break

    # Remove very short intervals by dropping the later peak.
    peaks = np.asarray(best_peaks, dtype=int)
    if len(peaks) >= 3:
        keep = np.ones(len(peaks), dtype=bool)
        intervals = np.diff(peaks) / fs
        for i, val in enumerate(intervals):
            if val < 1.5:
                keep[i + 1] = False
        peaks = peaks[keep]

    return peaks, best_props


def detect_troughs(clean, peaks, fs=100.0):
    troughs, _ = signal.find_peaks(-np.asarray(clean), distance=int(round(1.0 * fs)))
    return troughs.astype(int)


def respiratory_rate_signal(peaks, n_samples, fs=100.0):
    peaks = np.asarray(peaks, dtype=int)
    rate = np.full(n_samples, np.nan, dtype=float)
    if len(peaks) < 2:
        return rate

    intervals_s = np.diff(peaks) / fs
    bpm = 60.0 / intervals_s
    mid_t = (peaks[:-1] + peaks[1:]) / (2.0 * fs)
    valid = np.isfinite(bpm) & (bpm > 0) & (bpm < 60) & np.isfinite(mid_t)
    if np.sum(valid) == 0:
        return rate
    if np.sum(valid) == 1:
        rate[:] = bpm[valid][0]
        return rate

