print("Sleep/wake first 30:")
print(sw.head(30).to_string())
print("Sleep/wake last 30:")
print(sw.tail(30).to_string())

# Normalize expected output from BioPsyKit sleep_endpoints.
# BioPsyKit compute_sleep_endpoints returns times as strings/timestamps and durations in hours.
key_candidates = {
    "sleep_onset": ["sleep_onset", "sleep onset", "sleep_start", "sleep_start_time"],
    "wake_onset": ["wake_onset", "wake onset", "wake_up", "wake_time", "sleep_end", "wake_up_time"],
    "total_sleep_duration": ["total_sleep_duration", "total sleep duration", "total_sleep_time", "sleep_duration", "tst"],
}
norm_to_key = {str(k).lower().replace(" ", "_").replace("-", "_"): k for k in endpoints.keys()}
print("\nNormalized endpoint key map:", norm_to_key)

pred = {}
for target, candidates in key_candidates.items():
    for cand in candidates:
        norm = cand.lower().replace(" ", "_").replace("-", "_")
        if norm in norm_to_key:
            pred[target] = endpoints[norm_to_key[norm]]
            break

# If BioPsyKit endpoint names are abbreviated, handle them explicitly after inspection.
fallback_map = {
    "sleep_onset": ["sleep_onset_time", "sleeponset", "start_sleep_time"],
    "wake_onset": ["wake_onset_time", "wakeonset", "wake_after_sleep_onset_time", "end_sleep_time"],
    "total_sleep_duration": ["tst", "total_sleep_time", "sleep_period_time"],
}
for target, candidates in fallback_map.items():
    if target not in pred:
        for cand in candidates:
            if cand in norm_to_key:
                pred[target] = endpoints[norm_to_key[cand]]
                break

def to_jsonable(x):
    if isinstance(x, pd.Timestamp):
        return str(x)
    if isinstance(x, pd.Timedelta):
        return str(x)
    if hasattr(x, "item"):
        try:
            x = x.item()
        except Exception:
            pass
    if hasattr(x, "isoformat") and not isinstance(x, (int, float, str, bool)):
        try:
            return x.isoformat()
        except Exception:
            pass
    return x

pred = {k: to_jsonable(v) for k, v in pred.items()}
print("\nExtracted pred:", pred)

Path("pred_results").mkdir(exist_ok=True)
if set(pred.keys()) != {"sleep_onset", "wake_onset", "total_sleep_duration"}:
    # Write a diagnostic file but fail loudly so next turn can fix based on printed endpoint keys.
    with open("pred_results/endpoint_dump.json", "w") as f:
        json.dump({str(k): to_jsonable(v) for k, v in endpoints.items()}, f, indent=2)
    raise RuntimeError(f"Could not map all required keys; got {pred.keys()}")

with open("pred_results/imu_pred.json", "w") as f:
    json.dump(pred, f, indent=2)
print("Wrote pred_results/imu_pred.json:")
print(Path("pred_results/imu_pred.json").read_text())

