"""
Inspect available files to locate the saliva dataset or benchmark-provided data.
This turn prints the directory tree and any pickle/csv/json-like files found.
"""

from pathlib import Path
import os

def main():
    cwd = Path.cwd()
    print("Current working directory:", cwd)

    print("\nDirectory tree (limited depth 5, first 300 entries):")
    count = 0
    for root, dirs, files in os.walk("."):
        rel = Path(root)
        depth = len(rel.parts) - (0 if str(rel) == "." else 1)
        if depth > 5:
            dirs[:] = []
            continue
        dirs[:] = sorted(dirs)
        files = sorted(files)
        indent = "  " * max(depth, 0)
        print(f"{indent}{rel}/")
        count += 1
        for f in files:
            p = rel / f
            try:
                size = p.stat().st_size
            except Exception:
                size = "?"
            print(f"{indent}  {f}  ({size} bytes)")
            count += 1
            if count >= 300:
                print("... truncated ...")
                return

    print("\nCandidate data files:")
    exts = {".pkl", ".pickle", ".csv", ".tsv", ".xlsx", ".xls", ".json", ".parquet", ".feather"}
    candidates = []
    for base in [Path("."), Path(".."), Path("/data/lab/VeriFront/runs/sab_85/frontier")]:
        if base.exists():
            for p in base.rglob("*"):
                if p.is_file() and (p.suffix.lower() in exts or "saliva" in str(p).lower()):
                    candidates.append(p)
    seen = set()
    for p in candidates:
        rp = p.resolve()
        if rp in seen:
            continue
        seen.add(rp)
        try:
            print(" -", p, "size:", p.stat().st_size)
        except Exception as e:
            print(" -", p, "stat error:", e)

if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
Broader filesystem inspection to locate saliva_data/data.pkl.
Prints matching paths and benchmark directory metadata.
"""

from pathlib import Path
import os
import subprocess

def safe_walk(base, max_depth=6, max_entries=500):
    base = Path(base)
    print(f"\nWalking {base} (exists={base.exists()}):")
    if not base.exists():
        return
    count = 0
    for root, dirs, files in os.walk(base):
        rootp = Path(root)
        try:
            rel = rootp.relative_to(base)
            depth = 0 if str(rel) == "." else len(rel.parts)
        except Exception:
            depth = 0
        if depth > max_depth:
            dirs[:] = []
            continue
        # skip bulky/system-ish dirs
        dirs[:] = [d for d in sorted(dirs) if d not in {".git", "__pycache__", "site-packages", "node_modules"}]
        files = sorted(files)
        indent = "  " * depth
        print(f"{indent}{rootp.name}/")
        count += 1
        for f in files:
            p = rootp / f
            if f.endswith((".pkl", ".pickle", ".csv", ".json", ".py", ".txt", ".md")) or "saliva" in f.lower() or "data" in f.lower():
                try:
                    size = p.stat().st_size
                except Exception:
                    size = "?"
                print(f"{indent}  {f} ({size} bytes)")
                count += 1
        if count >= max_entries:
            print("... truncated ...")
            break

def main():
    print("cwd:", Path.cwd())
    for p in [Path("benchmark"), Path("pred_results")]:
        print(f"{p}: exists={p.exists()}, is_dir={p.is_dir()}")
        if p.exists():
            print("  stat:", p.stat())
            print("  entries:", list(p.iterdir())[:20] if p.is_dir() else "")

    # Use find for targeted names in likely roots.
    roots = [Path.cwd(), Path.cwd().parent, Path.cwd().parent.parent, Path("/data"), Path("/mnt"), Path("/tmp")]
    patterns = ["data.pkl", "*saliva*", "*.pkl"]
    found = []
    for root in roots:
        if not root.exists():
            continue
        print(f"\nTargeted search under {root}")
        for pattern in patterns:
            try:
                cmd = ["find", str(root), "-maxdepth", "8", "-iname", pattern, "-print"]
                res = subprocess.run(cmd, text=True, capture_output=True, timeout=30)
                lines = res.stdout.strip().splitlines() if res.stdout.strip() else []
                print(f" pattern {pattern}: {len(lines)} hits")
                for line in lines[:50]:
                    found.append(Path(line))
                    try:
                        print("  ", line, "size", Path(line).stat().st_size)
                    except Exception:
                        print("  ", line)
                if len(lines) > 50:
                    print("   ...")
            except subprocess.TimeoutExpired:
                print(f" pattern {pattern}: timed out")
            except Exception as e:
                print(f" pattern {pattern}: error {e}")

    safe_walk("benchmark", max_depth=8, max_entries=500)

if __name__ == "__main__":
    main()

