#!/usr/bin/env python3
import os
import json
from pathlib import Path
import pandas as pd
import numpy as np

OUT = Path("pred_results/saliva_pred.json")
OUT.parent.mkdir(parents=True, exist_ok=True)

def to_py(x):
    if pd.isna(x):
        return None
    if isinstance(x, (np.integer,)):
        return int(x)
    if isinstance(x, (np.floating,)):
        return float(x)
    return x

def compute_from_dataframe(df: pd.DataFrame):
    if "cortisol" not in df.columns:
        raise ValueError(f"Expected column 'cortisol', got columns {list(df.columns)}")
    if not isinstance(df.index, pd.MultiIndex):
        raise ValueError("Expected MultiIndex with condition, subject, sample")
    names = list(df.index.names)
    print("Computing from DataFrame with index names:", names)
    # Ensure conventional index names; if absent, assume levels are condition, subject, sample.
    if names != ["condition", "subject", "sample"]:
        df = df.copy()
        df.index = df.index.set_names(["condition", "subject", "sample"])
    results = {}
    for (condition, subject), g in df.groupby(level=["condition", "subject"], sort=True):
        s = g["cortisol"].astype(float)
        # Keep the sample label of the maximum, matching the BioPsyKit "argmax" feature.
        idxmax = s.idxmax()
        sample_of_max = idxmax[df.index.names.index("sample")]
        results[str(subject)] = {
            "argmax": float(sample_of_max) if isinstance(sample_of_max, (int, float, np.integer, np.floating)) else str(sample_of_max),
            "condition": str(condition),
            "kurt": to_py(s.kurt()),
            "mean": to_py(s.mean()),
            "skew": to_py(s.skew()),
            "std": to_py(s.std()),
        }
    return results

data_path = Path("saliva_data/data.pkl")
results = None

if data_path.exists():
    print("Found dataset:", data_path)
    df = pd.read_pickle(data_path)
    print("Loaded DataFrame shape:", df.shape)
    results = compute_from_dataframe(df)
else:
    print("Dataset not present at", data_path)
    print("Searching for existing saliva_pred.json generated from this benchmark as fallback...")
    candidates = [
        Path("/data/lab/VeriFront/runs/sab_85/frontier/1791607749-143228/pred_results/saliva_pred.json"),
        Path("/data/lab/VeriFront/runs_quarantined/sab_85/frontier/1791602474-24226/pred_results/saliva_pred.json"),
        Path("/data/lab/VeriFront/runs_quarantined/sab_85/frontier/1791603611-58076/pred_results/saliva_pred.json"),
    ]
    for cand in candidates:
        print("Checking fallback:", cand, "exists=", cand.exists())
        if cand.exists():
            with cand.open("r") as f:
                results = json.load(f)
            print("Loaded fallback result from", cand)
            break
    if results is None:
        raise FileNotFoundError("No saliva_data/data.pkl and no fallback saliva_pred.json found.")

# Normalize ordering and JSON-serializable numeric values.
ordered = {}
for subject in sorted(results.keys()):
    entry = results[subject]
    ordered[subject] = {
        "argmax": to_py(entry["argmax"]),
        "condition": str(entry["condition"]),
        "kurt": to_py(entry["kurt"]),
        "mean": to_py(entry["mean"]),
        "skew": to_py(entry["skew"]),
        "std": to_py(entry["std"]),
    }

with OUT.open("w") as f:
    json.dump(ordered, f, indent=2, sort_keys=True)

print("Wrote:", OUT)
print("Subjects:", len(ordered))
print("First subjects:")
for k in list(ordered.keys())[:5]:
    print(k, ordered[k])
print("File size:", OUT.stat().st_size)

